-- ═══════════════════════════════════════════════════════════════════
-- RISK EVENTS LOG
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS risk_events (
    id                  SERIAL PRIMARY KEY,
    timestamp_utc       TIMESTAMP WITH TIME ZONE NOT NULL,
    event_type          VARCHAR(40) NOT NULL,
    -- DAILY_DD_WARNING, DAILY_DD_SOFT_HALT, DAILY_DD_HARD_HALT,
    -- MONTHLY_DD_WARNING, CONSEC_LOSS_3, CONSEC_LOSS_5, CONSEC_LOSS_7,
    -- SPREAD_BLOWUP, HEARTBEAT_LOSS, FLASH_CRASH, RISK_STATE_CHANGE
    severity            VARCHAR(15) NOT NULL,
    asset               VARCHAR(10),
    detail              TEXT,
    metrics             JSONB,
    -- Relevant metrics at time of event

    created_at          TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE INDEX idx_risk_events_time ON risk_events(timestamp_utc);
CREATE INDEX idx_risk_events_type ON risk_events(event_type);


