-- ═══════════════════════════════════════════════════════════════════
-- CONFIGURATION HISTORY (audit trail)
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS config_history (
    id                  SERIAL PRIMARY KEY,
    timestamp_utc       TIMESTAMP WITH TIME ZONE NOT NULL,
    parameter           VARCHAR(50) NOT NULL,
    old_value           TEXT,
    new_value           TEXT NOT NULL,
