    reason              TEXT,

    created_at          TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);


-- ═══════════════════════════════════════════════════════════════════
-- MARKET DATA CACHE (for backtest validation)
-- ═══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS market_data_cache (
    id                  BIGSERIAL PRIMARY KEY,
    asset               VARCHAR(10) NOT NULL,
    timeframe           VARCHAR(5) NOT NULL,
    bar_time            TIMESTAMP WITH TIME ZONE NOT NULL,
    open                DECIMAL(14,5) NOT NULL,
    high                DECIMAL(14,5) NOT NULL,
    low                 DECIMAL(14,5) NOT NULL,
    close               DECIMAL(14,5) NOT NULL,
    volume              BIGINT,
    spread              INTEGER,

    UNIQUE(asset, timeframe, bar_time)
);

CREATE INDEX idx_market_data ON market_data_cache(asset, timeframe, bar_time);


-- ═══════════════════════════════════════════════════════════════════
-- USEFUL VIEWS
-- ═══════════════════════════════════════════════════════════════════

-- Rolling 30-day performance by asset
CREATE OR REPLACE VIEW v_asset_performance_30d AS
SELECT
    asset,
    COUNT(*) AS trade_count,
    SUM(CASE WHEN pnl_net > 0 THEN 1 ELSE 0 END) AS wins,
    SUM(CASE WHEN pnl_net <= 0 THEN 1 ELSE 0 END) AS losses,
    ROUND(SUM(CASE WHEN pnl_net > 0 THEN 1 ELSE 0 END)::DECIMAL / COUNT(*), 4) AS win_rate,
    ROUND(AVG(CASE WHEN pnl_net > 0 THEN pnl_net END), 2) AS avg_win,
    ROUND(AVG(CASE WHEN pnl_net < 0 THEN ABS(pnl_net) END), 2) AS avg_loss,
    ROUND(SUM(pnl_net), 2) AS total_pnl,
    ROUND(AVG(rr_achieved), 2) AS avg_rr,
    ROUND(SUM(CASE WHEN pnl_net > 0 THEN pnl_net ELSE 0 END) /
          NULLIF(SUM(CASE WHEN pnl_net < 0 THEN ABS(pnl_net) ELSE 0 END), 0), 2)
        AS profit_factor,
    ROUND(AVG(hold_duration_min), 0) AS avg_hold_min,
    ROUND(AVG(slippage_entry + slippage_exit), 2) AS avg_slippage
FROM trade_journal
WHERE exit_time_utc >= NOW() - INTERVAL '30 days'
  AND exit_time_utc IS NOT NULL
GROUP BY asset;

-- Today's trades
CREATE OR REPLACE VIEW v_today_trades AS
SELECT *
FROM trade_journal
WHERE entry_time_utc >= CURRENT_DATE
ORDER BY entry_time_utc DESC;

-- Current drawdown status
CREATE OR REPLACE VIEW v_drawdown_status AS
SELECT
    d.date,
    d.equity AS daily_start,
    e.equity AS current_equity,
    ROUND((d.equity - e.equity) / d.equity * 100, 2) AS daily_dd_pct,
    m.equity AS monthly_start,
    ROUND((m.equity - e.equity) / m.equity * 100, 2) AS monthly_dd_pct
FROM daily_equity_snapshot d
CROSS JOIN (
    SELECT equity FROM equity_snapshots ORDER BY timestamp_utc DESC LIMIT 1
) e
LEFT JOIN monthly_equity_snapshot m ON m.month_start = DATE_TRUNC('month', CURRENT_DATE)
WHERE d.date = CURRENT_DATE;

-- Performance by regime
CREATE OR REPLACE VIEW v_regime_performance AS
SELECT
    regime_at_entry,
    COUNT(*) AS trades,
    ROUND(SUM(CASE WHEN pnl_net > 0 THEN 1 ELSE 0 END)::DECIMAL / COUNT(*), 4) AS win_rate,
    ROUND(SUM(pnl_net), 2) AS total_pnl,
    ROUND(AVG(rr_achieved), 2) AS avg_rr
FROM trade_journal
WHERE exit_time_utc IS NOT NULL
GROUP BY regime_at_entry
ORDER BY total_pnl DESC;

-- Performance by entry trigger
CREATE OR REPLACE VIEW v_trigger_performance AS
SELECT
    m15_trigger_type,
    COUNT(*) AS trades,
    ROUND(SUM(CASE WHEN pnl_net > 0 THEN 1 ELSE 0 END)::DECIMAL / COUNT(*), 4) AS win_rate,
    ROUND(SUM(pnl_net), 2) AS total_pnl,
    ROUND(AVG(rr_achieved), 2) AS avg_rr
FROM trade_journal
WHERE exit_time_utc IS NOT NULL
GROUP BY m15_trigger_type
ORDER BY total_pnl DESC;


-- ═══════════════════════════════════════════════════════════════════
-- DATA RETENTION POLICY
-- ═══════════════════════════════════════════════════════════════════

-- equity_snapshots:     Keep 1 year at 5-min resolution, then downsample to hourly
-- regime_log:           Keep 6 months
-- trade_journal:        Keep forever (core audit trail)
-- signals:              Keep 1 year
-- market_data_cache:    Keep 2 years (for backtesting)

-- Downsampling job (run monthly via cron):
-- INSERT INTO equity_snapshots_hourly
-- SELECT DATE_TRUNC('hour', timestamp_utc) AS timestamp_utc,
--        AVG(balance), AVG(equity), ...
-- FROM equity_snapshots
-- WHERE timestamp_utc < NOW() - INTERVAL '1 year'
-- GROUP BY DATE_TRUNC('hour', timestamp_utc);
--
-- DELETE FROM equity_snapshots WHERE timestamp_utc < NOW() - INTERVAL '1 year';
